import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

@Service
class FileSystemStorageService {

    private final Path rootLocation;

    FileSystemStorageService(Path rootLocation) {
        this.rootLocation = rootLocation;
    }

    public void store(MultipartFile file) {
        try {
            if (file.isEmpty()) {
                throw new StorageException("Khong the luu file rong");
            }
            // Chuan hoa duong dan dich, roi kiem tra no PHAI nam trong rootLocation
            // de chong tan cong path traversal (vi du ten file "../../etc/passwd").
            Path destination = rootLocation.resolve(file.getOriginalFilename()).normalize().toAbsolutePath();
            if (!destination.getParent().equals(rootLocation.toAbsolutePath())) {
                throw new StorageException("Khong the luu file ngoai thu muc duoc phep");
            }
            try (var inputStream = file.getInputStream()) {
                Files.copy(inputStream, destination);
            }
        } catch (IOException e) {
            throw new StorageException("That bai khi luu file", e);
        }
    }

    static class StorageException extends RuntimeException {
        StorageException(String message) { super(message); }
        StorageException(String message, Throwable cause) { super(message, cause); }
    }
}

import org.springframework.core.io.Resource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
class FileDownloadController {

    private final StorageService storageService;

    FileDownloadController(StorageService storageService) {
        this.storageService = storageService;
    }

    @GetMapping("/files/{filename:.+}")
    public ResponseEntity<Resource> serveFile(@PathVariable String filename) {
        Resource file = storageService.loadAsResource(filename);
        return ResponseEntity.ok()
                .header(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=\"" + file.getFilename() + "\"")
                .body(file);
    }

    interface StorageService {
        Resource loadAsResource(String filename);
    }
}

import java.time.Duration;
import org.springframework.web.reactive.function.client.WebClient;

class ProductPriceClient {

    private final WebClient webClient;

    ProductPriceClient(WebClient.Builder builder) {
        this.webClient = builder
                .baseUrl("https://supplier.example.com/api")
                .build();
    }

    public PriceDTO fetchPrice(String sku) {
        return webClient.get()
                .uri("/prices/{sku}", sku)
                .header("X-Api-Key", "demo-key")
                .retrieve()
                .bodyToMono(PriceDTO.class)
                .timeout(Duration.ofSeconds(3))
                .block();
    }

    record PriceDTO(String sku, java.math.BigDecimal price) {}
}

import java.io.PrintWriter;
import java.util.List;
import java.util.stream.Collectors;

class CsvExporter {

    void writeOrders(PrintWriter writer, List<OrderRow> rows) {
        writer.println("id,customer,total");
        String body = rows.stream()
                .map(r -> String.join(",",
                        escape(r.id()), escape(r.customer()), escape(r.total())))
                .collect(Collectors.joining("\n"));
        writer.println(body);
    }

    // Neu truong chua dau phay, dau nhay kep, hoac xuong dong: bao trong nhay kep
    // va nhan doi moi dau nhay kep ben trong (theo quy uoc CSV/RFC 4180).
    private String escape(String value) {
        if (value.contains(",") || value.contains("\"") || value.contains("\n")) {
            return "\"" + value.replace("\"", "\"\"") + "\"";
        }
        return value;
    }

    record OrderRow(String id, String customer, String total) {}
}

